package com.oms.channel.platform;
import com.fasterxml.jackson.databind.JsonNode;
import com.oms.common.api.OrderGoodsClient;
import com.ruoyi.common.core.domain.R;
import org.junit.jupiter.api.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static com.oms.channel.platform.ChannelPlatformService.map;
class PlatformProductTest {
 ChannelPlatformTest f;PlatformProductService service;String shop;
 @BeforeEach void setup(){f=new ChannelPlatformTest();f.setup();for(String t:Arrays.asList("channel_stock_sync_run","channel_stock_sync_link","channel_stock_sync_group","channel_stock_sync_sim","channel_product_binding_event","channel_platform_product","channel_product_pull_item","channel_product_pull","channel_product_sim","channel_platform_item","channel_product_policy","channel_company_policy"))f.db.update("DELETE FROM "+t);f.simulation(true);f.service.simulate("QM",101,"tester");shop=f.db.queryForObject("SELECT expected_shop_id FROM channel_platform_binding WHERE channel_id=101",String.class);service=new PlatformProductService();service.db=f.db;service.settings=new ChannelSettings();service.settings.db=f.db;service.settings.products("QM",101);f.db.update("UPDATE channel_product_policy SET auto_pull=0,auto_bind=0");service.platform=f.service;service.transactionManager=new org.springframework.jdbc.datasource.DataSourceTransactionManager(f.db.getDataSource());service.logs=new PlatformInteractionLog();service.logs.db=f.db;service.logs.transactionManager=service.transactionManager;service.goods=mock(OrderGoodsClient.class);when(service.goods.goods(anyString(),anyList(),anyString())).thenAnswer(i->((List<?>)i.getArgument(1)).isEmpty()?R.ok(Collections.emptyList()):R.ok(Collections.singletonList(map("sku_sn",((List<?>)i.getArgument(1)).get(0),"goods_name","测试商品","is_package",0,"is_fd",0))));}
 @AfterEach void close(){if(f!=null)f.closePool();}
 JsonNode payload(String id,String status,String code,String props){return StockSyncPlatform.JSON.valueToTree(map("num_iid",id,"title","平台商品"+id,"approve_status",status,"num",5,"skus",map("sku",Collections.singletonList(map("sku_id","91"+id,"outer_id",code,"properties",props,"properties_name","蓝色;M","quantity",5)))));}
 void seed(String id,String status){f.db.update("INSERT INTO channel_product_sim(company_code,channel_id,item_id,payload) VALUES ('QM',101,?,?)",id,payload(id,status,"A","1:2").toString());}
 long upsert(){service.tx().execute(t->{service.upsert("QM",101,shop,"100",payload("100","onsale","A","1:2"),"tester");return null;});return f.db.queryForObject("SELECT id FROM channel_platform_product WHERE item_id='100'",Long.class);}
 Map<String,Object> bind(long id,String sku){return service.bind("QM",id,map("action","BIND","sku_sn",sku,"binding_revision",service.detail("QM",id).get("binding_revision"),"reason","核对确认"),"tester");}
 @Test void fullPullCoversSaleAndWarehouseAndDoesNotAutoBind(){seed("100","onsale");seed("200","instock");long task=PlatformInteractionLog.n(service.pull("QM",101,map("mode","ALL"),"tester"),"id");for(int i=0;i<3;i++)service.process("QM",task);assertEquals("SUCCESS",service.task("QM",task).get("state"));assertEquals(2,f.db.queryForObject("SELECT COUNT(*) FROM channel_platform_product WHERE binding_state='UNBOUND' AND oms_sku_sn IS NULL",Integer.class));assertEquals(1L,service.list("QM",101L,"","","instock",1,20).get("total"));assertTrue(f.client.requests.isEmpty());assertTrue(f.db.queryForObject("SELECT COUNT(*) FROM channel_interaction_log WHERE category='PRODUCT'",Integer.class)>0);}
 @Test void specifiedIdsUseDetailsDirectlyAndDeduplicate(){seed("100","onsale");seed("200","instock");long task=PlatformInteractionLog.n(service.pull("QM",101,map("mode","IDS","item_ids",Arrays.asList("100","100")),"tester"),"id");service.process("QM",task);assertEquals("SUCCESS",service.task("QM",task).get("state"));assertEquals(1,f.db.queryForObject("SELECT COUNT(*) FROM channel_platform_product",Integer.class));}
 @Test void explicitBindIsSharedAndRequiresRevision(){long id=upsert();assertNull(service.detail("QM",id).get("oms_sku_sn"));assertEquals(true,service.suggestions("QM",id).get("can_suggest"));assertEquals("BOUND",bind(id,"A").get("binding_state"));assertEquals(1,service.boundOptions("QM",101,"A").size());assertEquals("A",service.resolve("QM",101,Collections.singletonList(map("item_id","100","sku_id","91100"))).get(0).get("oms_sku_sn"));assertThrows(IllegalArgumentException.class,()->service.bind("QM",id,map("action","BIND","sku_sn","B","binding_revision",1,"reason","stale"),"tester"));assertThrows(IllegalArgumentException.class,()->service.detail("OTHER",id));}
 @Test void codeOrPropertiesChangeRequiresReviewButTitleDoesNot(){long id=upsert();bind(id,"A");long rev=PlatformInteractionLog.n(service.detail("QM",id),"binding_revision");JsonNode item=payload("100","onsale","A","1:2");((com.fasterxml.jackson.databind.node.ObjectNode)item).put("title","新标题");service.upsert("QM",101,shop,"100",item,"tester");assertEquals(rev,PlatformInteractionLog.n(service.detail("QM",id),"binding_revision"));service.upsert("QM",101,shop,"100",payload("100","onsale","B","1:3"),"tester");assertEquals("REVIEW",service.detail("QM",id).get("binding_state"));assertTrue(service.boundOptions("QM",101,"A").isEmpty());assertThrows(IllegalArgumentException.class,()->service.bound("QM",101,id,rev,"A"));bind(id,"A");assertEquals("BOUND",service.detail("QM",id).get("binding_state"));}
 @Test void removedSpecCannotRemainUsableAndReappearanceNeedsReview(){long id=upsert();bind(id,"A");JsonNode item=payload("100","onsale","A","1:2");((com.fasterxml.jackson.databind.node.ObjectNode)item.path("skus").path("sku").get(0)).put("status","delete");service.upsert("QM",101,shop,"100",item,"tester");assertEquals(0,service.detail("QM",id).get("present"));assertEquals("REVIEW",service.resolve("QM",101,Collections.singletonList(map("item_id","100","sku_id","91100"))).get(0).get("binding_state"));service.upsert("QM",101,shop,"100",payload("100","onsale","A","1:2"),"tester");assertEquals("REVIEW",service.detail("QM",id).get("binding_state"));}
 @Test void pausedSyncStillOwnsTargetUntilExplicitExit(){long id=upsert();bind(id,"A");f.db.update("INSERT INTO channel_stock_sync_group(company_code,channel_id,sku_sn,created_by) VALUES ('QM',101,'A','tester')");long group=f.db.queryForObject("SELECT id FROM channel_stock_sync_group LIMIT 1",Long.class);f.db.update("INSERT INTO channel_stock_sync_link(company_code,channel_id,group_id,item_id,sku_id,name,weight,enabled) VALUES ('QM',101,?,'100','91100','paused',100,0)",group);assertThrows(IllegalArgumentException.class,()->bind(id,"B"));f.db.update("UPDATE channel_stock_sync_link SET retired_at=NOW()");assertEquals("B",bind(id,"B").get("oms_sku_sn"));}
 @Test void sameSkuWithoutChangesIsANoop(){long id=upsert();bind(id,"A");long rev=PlatformInteractionLog.n(bind(id,"A"),"binding_revision");assertEquals(2,rev);assertEquals("A",service.bound("QM",101,id,2,"A").get("oms_sku_sn"));}
 @Test void duplicateShopTaskAndActiveRetryAreRejected(){seed("100","onsale");long id=PlatformInteractionLog.n(service.pull("QM",101,map("mode","IDS","item_ids",Collections.singletonList("100")),"tester"),"id");assertThrows(IllegalArgumentException.class,()->service.pull("QM",101,map("mode","ALL"),"tester"));f.db.update("UPDATE channel_product_pull SET state='FAILED' WHERE id=?",id);service.pull("QM",101,map("mode","ALL"),"tester");assertThrows(IllegalArgumentException.class,()->service.retry("QM",id));}
 @Test void wrongShopIdentityStopsCatalogCommit(){long id=upsert();bind(id,"A");f.db.update("UPDATE channel_platform_binding SET expected_shop_id='DIFFERENT' WHERE channel_id=101");assertThrows(IllegalArgumentException.class,()->service.upsert("QM",101,shop,"100",payload("100","onsale","B","1:2"),"tester"));assertEquals("A",service.detail("QM",id).get("outer_id"));assertTrue(service.boundOptions("QM",101,"A").isEmpty());}
 @Test void expiredWorkerCannotOverwriteNewOwnerItemState(){long task=PlatformInteractionLog.n(service.pull("QM",101,map("mode","IDS","item_ids",Collections.singletonList("100")),"tester"),"id");service.platform=mock(ChannelPlatformService.class);when(service.platform.stockCall(anyString(),anyLong(),anyString(),anyMap(),anyBoolean(),anyMap())).thenAnswer(i->{f.db.update("UPDATE channel_product_pull SET lease_token='NEW_OWNER',lease_until=DATE_ADD(NOW(),INTERVAL 180 SECOND) WHERE id=?",task);throw new IllegalArgumentException("原调用超时");});service.process("QM",task);assertEquals("PENDING",f.db.queryForObject("SELECT state FROM channel_product_pull_item WHERE task_id=?",String.class,task));assertEquals("NEW_OWNER",f.db.queryForObject("SELECT lease_token FROM channel_product_pull WHERE id=?",String.class,task));}
 @Test void failureIsRetainedAndRetryCanCompleteWithoutDuplicateRows(){long task=PlatformInteractionLog.n(service.pull("QM",101,map("mode","IDS","item_ids",Collections.singletonList("100")),"tester"),"id");service.process("QM",task);assertEquals("PARTIAL",service.task("QM",task).get("state"));seed("100","onsale");service.retry("QM",task);service.process("QM",task);assertEquals("SUCCESS",service.task("QM",task).get("state"));assertEquals(1,f.db.queryForObject("SELECT COUNT(*) FROM channel_platform_product",Integer.class));}
 @Test void enabledDefaultsCreateScheduledPullAndBindMultipleLinks(){f.db.update("DELETE FROM channel_product_policy");Map<String,Object> policy=service.settings.products("QM",101);assertEquals(1,policy.get("auto_pull"));assertEquals(1,policy.get("auto_bind"));seed("100","onsale");seed("200","instock");for(int i=0;i<3;i++)service.scan("QM");assertEquals(2,f.db.queryForObject("SELECT COUNT(*) FROM channel_platform_product WHERE binding_state='BOUND' AND binding_source='AUTO' AND oms_sku_sn='A'",Integer.class));assertEquals(1,f.db.queryForObject("SELECT COUNT(*) FROM channel_product_pull WHERE trigger_source='SCHEDULER'",Integer.class));service.scan("QM");assertEquals(1,f.db.queryForObject("SELECT COUNT(*) FROM channel_product_pull",Integer.class));assertEquals(2L,service.items("QM",101L,"","BOUND","",1,20).get("total"));}
 @Test void automaticBindingIsExactAndAmbiguityIsRetained(){long id=upsert();f.db.update("UPDATE channel_product_policy SET auto_bind=1");when(service.goods.goods(anyString(),anyList(),anyString())).thenReturn(R.ok(Arrays.asList(map("sku_sn","a"),map("sku_sn","a"))));assertEquals(0,service.autoBind("QM",101L));assertEquals("商家编码未匹配到OMS SKU",service.detail("QM",id).get("match_issue"));f.db.update("UPDATE channel_platform_product SET next_match_at=NOW()");when(service.goods.goods(anyString(),anyList(),anyString())).thenReturn(R.ok(Arrays.asList(map("sku_sn","A"),map("sku_sn","A"))));assertEquals(0,service.autoBind("QM",101L));assertEquals("商家编码匹配到多个OMS SKU",service.detail("QM",id).get("match_issue"));f.db.update("UPDATE channel_platform_product SET next_match_at=NOW()");when(service.goods.goods(anyString(),anyList(),anyString())).thenReturn(R.ok(Collections.singletonList(map("sku_sn","A","goods_name","新建商品"))));assertEquals(1,service.autoBind("QM",101L));assertEquals("AUTO",service.detail("QM",id).get("binding_source"));assertEquals(0,service.autoBind("QM",101L));}
 @Test void manualUnbindAndIgnoreAreProtectedFromAutomaticRebinding(){long id=upsert();f.db.update("UPDATE channel_product_policy SET auto_bind=1");bind(id,"A");service.bind("QM",id,map("action","UNBIND","binding_revision",2,"reason","人工决定解绑"),"tester");assertEquals(0,service.autoBind("QM",101L));assertNull(service.detail("QM",id).get("oms_sku_sn"));service.bind("QM",id,map("action","IGNORE","binding_revision",3,"reason","人工忽略"),"tester");assertEquals(0,service.autoBind("QM",101L));assertEquals("IGNORED",service.detail("QM",id).get("binding_state"));}
 @Test void changedIdentityNeverAutomaticallyRetargets(){long id=upsert();f.db.update("UPDATE channel_product_policy SET auto_bind=1");service.autoBind("QM",101L);service.upsert("QM",101,shop,"100",payload("100","onsale","B","2:3"),"tester");assertEquals(0,service.autoBind("QM",101L));assertEquals("A",service.detail("QM",id).get("oms_sku_sn"));assertEquals("REVIEW",service.detail("QM",id).get("binding_state"));}
 @Test void groupedProductHasExpandableSkusAndBindingCounts(){JsonNode item=payload("100","onsale","A","1:2");((com.fasterxml.jackson.databind.node.ArrayNode)item.path("skus").path("sku")).add(StockSyncPlatform.JSON.valueToTree(map("sku_id","91101","outer_id","MISSING","properties","1:3","quantity",2)));service.upsert("QM",101,shop,"100",item,"tester");f.db.update("UPDATE channel_product_policy SET auto_bind=1");service.autoBind("QM",101L);Map<String,Object> page=service.items("QM",101L,"","PARTIAL","",1,20);assertEquals(1L,page.get("total"));Map<?,?> row=((List<Map<String,Object>>)page.get("rows")).get(0);assertEquals(2L,((Number)row.get("sku_count")).longValue());assertEquals(1L,((Number)row.get("bound_count")).longValue());assertEquals(0,((List<?>)row.get("skus")).size());assertEquals(2,((List<?>)service.specs("QM",101,"100",1,50).get("rows")).size());}
 @Test void unknownOrderProductIsQueuedOnceAndResolvesAfterAutomaticProcessing(){seed("100","onsale");f.db.update("UPDATE channel_product_policy SET auto_pull=1,auto_bind=1");List<Map<String,Object>> ids=Collections.singletonList(map("item_id","100","sku_id","91100"));assertEquals("SYNC_PENDING",service.resolve("QM",101,ids).get(0).get("binding_state"));service.resolve("QM",101,ids);assertEquals(1,f.db.queryForObject("SELECT COUNT(*) FROM channel_product_pull",Integer.class));long task=f.db.queryForObject("SELECT id FROM channel_product_pull",Long.class);service.process("QM",task);service.autoBind("QM",101L);assertEquals("BOUND",service.resolve("QM",101,ids).get(0).get("binding_state"));}
 @Test void companySettingsAreVersionedAndValidateRetention(){Map<String,Object> p=service.settings.products("QM",101);p.put("interval_minutes",4);assertThrows(IllegalArgumentException.class,()->service.settings.saveProducts("QM",101,p,"tester"));p.put("interval_minutes",30);service.settings.saveProducts("QM",101,p,"tester");assertThrows(IllegalArgumentException.class,()->service.settings.saveProducts("QM",101,p,"tester"));assertThrows(IllegalArgumentException.class,()->service.settings.products("OTHER",101));assertThrows(IllegalArgumentException.class,()->service.settings.saveRetention("QM",map("summary_days",10,"payload_days",20,"revision",0),"tester"));Map<String,Object> r=service.settings.retention("QM");r.put("summary_days",120);r.put("payload_days",30);assertEquals(120,service.settings.saveRetention("QM",r,"tester").get("summary_days"));assertEquals(90,service.settings.retention("OTHER").get("summary_days"));}
 @Test void productCallsArePreciselyLinkedAndDistinguishPlatformAndSave(){seed("100","onsale");long task=PlatformInteractionLog.n(service.pull("QM",101,map("mode","IDS","item_ids",Collections.singletonList("100")),"tester"),"id");service.process("QM",task);PlatformLogQuery q=new PlatformLogQuery();q.logs=service.logs;Map<String,String> input=new HashMap<>();input.put("channelId","101");input.put("itemId","100");List<Map<String,Object>> rows=(List<Map<String,Object>>)q.list("QM",input).get("rows");assertTrue(rows.stream().anyMatch(r->"PRODUCT_DETAIL".equals(r.get("action"))));assertTrue(rows.stream().anyMatch(r->"SIMULATION".equals(r.get("entry_kind"))));input.put("itemId","200");assertTrue(((List<?>)q.list("QM",input).get("rows")).isEmpty());}

 @Test void unavailableGoodsServiceIsVisibleAndDoesNotCreateBindings(){long id=upsert();f.db.update("UPDATE channel_product_policy SET auto_bind=1");when(service.goods.goods(anyString(),anyList(),anyString())).thenThrow(new RuntimeException("down"));assertEquals(0,service.autoBind("QM",101L));assertEquals("OMS商品服务暂不可用，稍后自动重试",service.detail("QM",id).get("match_issue"));assertNull(service.detail("QM",id).get("oms_sku_sn"));}
 @Test void repeatedUnknownOrderReadReusesRetryableFailedTask(){f.db.update("UPDATE channel_product_policy SET auto_pull=1");List<Map<String,Object>> ids=Collections.singletonList(map("item_id","100","sku_id","91100"));service.resolve("QM",101,ids);long task=f.db.queryForObject("SELECT id FROM channel_product_pull",Long.class);f.db.update("UPDATE channel_product_pull SET state='PARTIAL',attempts=1 WHERE id=?",task);service.resolve("QM",101,ids);assertEquals(1,f.db.queryForObject("SELECT COUNT(*) FROM channel_product_pull",Integer.class));}

 @Test void pullAndNotificationRollbackTogetherAndRetryUsesNewVersion(){
  f.db.update("DELETE FROM oms_message_attempt");f.db.update("DELETE FROM oms_message_outbox");com.oms.messaging.MessageOutbox out=new com.oms.messaging.MessageOutbox();out.db=f.db;
  org.springframework.test.util.ReflectionTestUtils.setField(out,"transactionManager",service.transactionManager);org.springframework.test.util.ReflectionTestUtils.setField(out,"service","channel");org.springframework.beans.factory.ObjectProvider<com.oms.messaging.MessageOutbox> provider=mock(org.springframework.beans.factory.ObjectProvider.class);when(provider.getIfAvailable()).thenReturn(out);service.messages=provider;
  service.tx().execute(status->{service.pull("QM",101,map("mode","IDS","item_ids",Collections.singletonList("100")),"tester");status.setRollbackOnly();return null;});assertEquals(0,f.db.queryForObject("SELECT COUNT(*) FROM channel_product_pull",Integer.class));assertEquals(0,f.db.queryForObject("SELECT COUNT(*) FROM oms_message_outbox",Integer.class));
  long id=PlatformInteractionLog.n(service.pull("QM",101,map("mode","IDS","item_ids",Collections.singletonList("100")),"tester"),"id");service.wake("QM",id);assertEquals(1,f.db.queryForObject("SELECT COUNT(*) FROM oms_message_outbox",Integer.class));f.db.update("UPDATE channel_product_pull SET state='FAILED' WHERE id=?",id);service.retry("QM",id);assertEquals(2,f.db.queryForObject("SELECT COUNT(*) FROM oms_message_outbox",Integer.class));assertEquals(2,f.db.queryForObject("SELECT MAX(business_version) FROM oms_message_outbox",Integer.class));
 }
 @Test void rateIdentityUsesPlatformApplicationAndShopRatherThanLocalRowIds(){long id=PlatformInteractionLog.n(service.pull("QM",101,map("mode","IDS","item_ids",Collections.singletonList("100")),"tester"),"id");ProductPullMessage message=new ProductPullMessage();message.products=service;List<String> before=message.rateKeys("QM",map("business_id",id));assertEquals(2,before.size());assertTrue(before.stream().allMatch(k->k.matches("[a-f0-9]{64}")));f.db.update("UPDATE channel_platform_app SET app_key=CONCAT(app_key,'other') WHERE id=(SELECT app_id FROM channel_platform_binding WHERE channel_id=101)");List<String> after=message.rateKeys("QM",map("business_id",id));assertNotEquals(before.get(0),after.get(0));assertEquals(before.get(1),after.get(1));}
}
